324	  private readonly cache = new Map<string, ChatSession>();
325	
326	  constructor(private redis: RedisClient) {}
327	
328	  create(sessionId: string, userId: string | number, options?: SessionCreateOptions): ChatSession {
329	    const session: ChatSession = {sessionId, userId, entries: [], ...options};
330	    this.cache.set(sessionId, session);
331	    return session;
332	  }
333	
