336	    if (cached) return cached;
337	
338	    const stored = await this.redis.get(`session:${sessionId}`);
339	    return stored ? (JSON.parse(stored) as ChatSession) : undefined;
340	  }
341	
342	  // Eviction, not erasure: the engine never calls this, and a durable delete here would destroy history.
343	  delete(sessionId: string): boolean {
