/** Tracks a server a suite started by hand, so the teardown below stops it too. */
export function trackServer(hal: HalServer): void {
  servers.push(hal);
}

/** Waits until check holds, on a 10 ms tick, for frame traffic a test cannot await directly. */
export async function eventually(check: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
}

/** Terminates every tracked socket, waits for each server to see its sockets close, then stops it, so no close lands after a suite restores its logger. */
export async function drainAndStopEngines(): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
}

