// Re-anchors [validated by: <title>](<test>#Lnn) citations after line shifts in four edited test files.
import {readFileSync, writeFileSync} from 'node:fs';

const root = process.argv[2];
const SPEC_FILES = process.argv.slice(3);
const TEST_FILES = [
  'src/transport/conversationList.acceptance.test.ts',
  'src/transport/sessionResume.test.ts',
  'src/transport/ws/messageHandler.test.ts',
  'src/transport/ws/validation.test.ts',
];

const index = new Map();
for (const test of TEST_FILES) {
  const titles = new Map();
  const lines = readFileSync(`${root}/${test}`, 'utf8').split('\n');
  lines.forEach((line, i) => {
    const m = /^\s*(?:it|test|describe)\((['"`])(.+?)\1/.exec(line);
    if (m && !titles.has(m[2])) titles.set(m[2], i + 1);
  });
  index.set(test, titles);
}

let rewritten = 0;
const misses = [];
for (const spec of SPEC_FILES) {
  const path = `${root}/${spec}`;
  const updated = readFileSync(path, 'utf8')
    .split('\n')
    .map(line =>
      line.replace(/\[validated by: ([^\]]+)\]\(([^)#]+)#L(\d+)\)/g, (all, title, href, oldLine) => {
        const test = TEST_FILES.find(t => href.endsWith(t));
        if (test === undefined) return all;
        const line = index.get(test).get(title);
        if (line === undefined) {
          misses.push(`${spec}: "${title}" -> ${href}`);
          return all;
        }
        if (String(line) === oldLine) return all;
        rewritten += 1;
        return `[validated by: ${title}](${href}#L${line})`;
      })
    )
    .join('\n');
  writeFileSync(path, updated);
}
console.log(`rewritten: ${rewritten}`);
for (const miss of misses) console.log(`UNRESOLVED ${miss}`);

